from langsmith import traceable
import openai

@traceable(
    name="symptom_analysis",
    metadata={"service": "healthbot", "compliance": "hipaa"},
    tags=["production", "patient-facing"]
)
def analyze_symptoms(symptoms: str, patient_id: str) -> dict:
    # Custom PII redaction before LLM call
    redacted = redact_phi(symptoms)

    response = openai.ChatCompletion.create(
        model="gpt-4",
        messages=[{"role": "user", "content": redacted}],
        temperature=0.3
    )

    return {
        "diagnosis": response.choices[0].message.content,
        "patient_id_hash": hash(patient_id),
        "model": "gpt-4"
    }

# LangSmith custom faithfulness evaluator
from langsmith import evaluate

def faithfulness_scorer(run, example):
    answer = run.outputs["answer"]
    context = run.outputs["context"]
    prompt = f"""Does this answer contain only information from the context?
    Context: {context}
    Answer: {answer}
    Score 0-1:"""
    score = llm.predict(prompt)  # LLM-as-judge
    return {"key": "faithfulness", "score": float(score)}

