# Multi-tenant trace tagging with LangSmith
from langsmith import Client
from langsmith.run_helpers import traceable

client = Client()

@traceable(
    run_type="chain",
    project_name="banking_prod",
    metadata_fn=lambda inputs: {
        "tenant": inputs.get("tenant_id"),
        "user_segment": inputs.get("segment"),
        "contains_pii": detect_pii(inputs["query"]),
        "compliance_tier": "high" if inputs.get("segment") == "wealth" else "standard"
    }
)
def rag_pipeline(query: str, tenant_id: str, segment: str):
    context = retrieve(query, tenant=tenant_id)
    answer = llm.invoke(context + query)
    # Automatic trace capture with tenant isolation
    return {"answer": answer, "sources": context}

# Configure retention and export to cold storage
client.create_dataset(
    "banking_prod_archive",
    description="7-year FINRA retention",
    metadata={"retention_years": 7, "storage_tier": "glacier"}
)
